{"packet_id": "D005-01", "doc_id": "D005", "jurisdiction": "CA", "category": "application_screening_fees", "lifecycle": "enacted", "title": "California tenant screening fee cap, 2026", "requirement": "A landlord may charge a prospective tenant a screening fee only up to the statewide cap, must supply the credit report, a receipt and any unused portion, and may not charge it when no unit is available.", "key_value": "$68.96 (2026 screening fee cap)", "coverage_conditions": "Prospective tenants screened for residential rental units in California; reusable screening reports must be accepted.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": "No screening fee may be charged when no rental unit is actually available, or to applicants not considered under a first-qualified-applicant policy.", "penalty": "Refund of any unused portion of the screening fee to any applicant not selected.", "effective_date": "2026", "citation": "Cal. Civ. Code § 1950.6", "quoted_span": "The maximum tenant screening fee for 2026 is $68.96", "interaction": null, "confidence": 0.7, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D005-01", "doc_id": "D005", "jurisdiction": "Berkeley, CA", "category": "application_screening_fees", "lifecycle": "enacted", "title": "Berkeley tenant screening fee rights notice", "requirement": "An owner who charges a fee to process a rental application must give the applicant a clear and conspicuous tenant screening fee rights statement and the state maximum fee cap before receiving the fee.", "key_value": null, "coverage_conditions": "Owners and their agents renting residential property in Berkeley who charge an application or credit report fee.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": null, "effective_date": null, "citation": "Berkeley Mun. Code § 13.78.010", "quoted_span": "the owner must provide, either in the rental application or in a separate disclosure before receiving the fee, a clear and conspicuous tenant screening fee rights statement and a statement of the maximum fee cap permitted under California Civil Code Section 1950.6(b).", "interaction": "Berkeley notice duty layers on top of the state fee cap in Civil Code 1950.6.", "confidence": 0.7, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D005-01", "doc_id": "D005", "jurisdiction": "Berkeley, CA", "category": "application_screening_fees", "lifecycle": "enacted", "title": "Berkeley ban on non-refundable renewal fees", "requirement": "An owner may not charge an existing tenant a non-refundable fee to renew a tenancy, including fees tied to a roommate leaving or to adding or replacing a roommate.", "key_value": null, "coverage_conditions": "Owners of residential rental property in Berkeley and their agents, as to existing tenants; applies despite contrary lease language.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": "applies to all residential rental agreements regardless of contrary lease terms"}, "exemptions": null, "penalty": "Any lease provision violating the chapter is unenforceable.", "effective_date": null, "citation": "Berkeley Mun. Code § 13.78.016", "quoted_span": "An owner of residential rental property (or the owner’s agent) cannot charge a non-refundable fee to any existing tenant for the purpose of renewing a tenancy, in whole or in part, including any fee associated with the departure of a roommate or to request to add or replace a roommate in a pre-existing household.", "interaction": null, "confidence": 0.7, "conflict_flag": false, "conflict_note": null}
